{
  "story_id": "S10",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Appeal a declined claim by replying to the decision letter",
      "technique": "positive",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member has a declined claim and its decision letter.",
        "The member can state why they think the decision is wrong."
      ],
      "steps": [
        "Reply to the decision letter with the reason the member thinks the decision is wrong."
      ],
      "expected_result": "The member can appeal the declined claim by replying to the decision letter, and the appeal states the member's reason."
    },
    {
      "case_id": "TC02",
      "title": "Appeal a declined claim through the member portal",
      "technique": "positive",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member has a declined claim and access to the member portal.",
        "The member can state why they think the decision is wrong."
      ],
      "steps": [
        "Submit an appeal for the declined claim through the member portal, stating why the member thinks the decision is wrong."
      ],
      "expected_result": "The member can appeal the declined claim through the member portal, and the appeal states the member's reason."
    },
    {
      "case_id": "TC03",
      "title": "Appeal states a reason without adding missing claim information",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "The member can state why they think the decision is wrong."
      ],
      "steps": [
        "Submit an appeal that states the reason but includes no additional information from the original claim."
      ],
      "expected_result": "The appeal states why the member thinks the decision is wrong. The acceptance criteria do not require additional information to be included."
    },
    {
      "case_id": "TC04",
      "title": "Include a missing referral with the appeal",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "A referral was missing from the original claim."
      ],
      "steps": [
        "Submit an appeal stating why the member thinks the decision is wrong and include the referral."
      ],
      "expected_result": "The appeal states the member's reason and includes the referral."
    },
    {
      "case_id": "TC05",
      "title": "Include a missing pre-authorisation number with the appeal",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "A pre-authorisation number was missing from the original claim."
      ],
      "steps": [
        "Submit an appeal stating why the member thinks the decision is wrong and include the pre-authorisation number."
      ],
      "expected_result": "The appeal states the member's reason and includes the pre-authorisation number."
    },
    {
      "case_id": "TC06",
      "title": "Include a provider's description of an accidental injury",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "A provider's description showing the injury was accidental was missing from the original claim."
      ],
      "steps": [
        "Submit an appeal stating why the member thinks the decision is wrong and include the provider's description."
      ],
      "expected_result": "The appeal states the member's reason and includes the provider's description showing the injury was accidental."
    },
    {
      "case_id": "TC07",
      "title": "Appeal does not state why the decision is wrong",
      "technique": "negative",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim."
      ],
      "steps": [
        "Attempt to submit an appeal without stating why the member thinks the decision is wrong."
      ],
      "expected_result": "The appeal content does not state why the member thinks the decision is wrong, so it does not meet AC2. The acceptance criteria do not specify how the system handles an appeal submitted without a reason."
    },
    {
      "case_id": "TC08",
      "title": "Appeal is reviewed by a senior assessor not involved in the original decision",
      "technique": "positive",
      "covers": ["AC3"],
      "preconditions": [
        "A claim decision has been appealed.",
        "The original decision-maker and the appeal reviewer can be identified."
      ],
      "steps": [
        "Complete the appeal review and check the reviewer's role and involvement in the original decision."
      ],
      "expected_result": "The appeal is reviewed by a senior claims assessor who was not involved in the original decision."
    },
    {
      "case_id": "TC09",
      "title": "Original decision-maker does not review the appeal",
      "technique": "negative",
      "covers": ["AC3"],
      "preconditions": [
        "A claim decision has been appealed.",
        "The original decision-maker is identified."
      ],
      "steps": [
        "Check who reviews the appeal."
      ],
      "expected_result": "The reviewer is not the person involved in the original decision. The reviewer must also be a senior claims assessor."
    },
    {
      "case_id": "TC10",
      "title": "Service dissatisfaction is handled as a complaint",
      "technique": "negative",
      "covers": ["AC4"],
      "preconditions": [
        "The member is dissatisfied with the service and is not disputing a claim decision."
      ],
      "steps": [
        "Raise the service dissatisfaction and check how it is handled."
      ],
      "expected_result": "The dissatisfaction is handled as a complaint, not as an appeal."
    }
  ]
